const input = $input.first().json;
const classId = input.id;
const className = input.name || 'Unnamed class';
return {
  json: {
    class_id: classId,
    class_name: className,
    weeks: 4,
    limit: 12,
    llm_provider: 'ollama',
    llm_model: 'qwen2.5:3b'
  }
};

const input = $('Build Ollama Prompt').first().json;
const sourceTexts = Array.isArray(input.raw_rows) ? input.raw_rows.map((row) => String(row.comment_text || '').replace(/\s+/g, ' ').trim()).filter(Boolean) : [];
const normalize = (value) => String(value || '').replace(/[`"“”'']/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const rawOutput = typeof $json.text === 'string'
  ? $json.text
  : typeof $json.output === 'string'
    ? $json.output
    : typeof $json.response?.text === 'string'
      ? $json.response.text
      : typeof $json.error === 'string'
        ? ''
        : JSON.stringify($json || {});
if (input.status_from_raw !== 'ready' || !Array.isArray(input.raw_rows) || input.raw_rows.length === 0) {
  return {
    json: {
      class_id: input.class_id,
      class_name: input.class_name,
      status: 'no_safe_batch',
      batch_size: Number(input.batch_size || 0),
      snippets_written: 0,
      week_start: input.week_start,
      source_window: input.source_window,
      snippets: [],
      reason: input.raw_reason || 'no_safe_batch',
      llm_output_rejected: false,
      llm_provider: input.llm_provider,
      llm_model: input.llm_model,
    }
  };
}
if ($json.error) {
  return {
    json: {
      class_id: input.class_id,
      class_name: input.class_name,
      status: 'unsafe_output',
      batch_size: Number(input.batch_size || 0),
      snippets_written: 0,
      week_start: input.week_start,
      source_window: input.source_window,
      snippets: [],
      reason: `ollama_error:${String($json.error).slice(0, 180)}`,
      llm_output_rejected: true,
      llm_provider: input.llm_provider,
      llm_model: input.llm_model,
    }
  };
}
let parsed;
try {
  const cleaned = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
  if (Array.isArray(parsed)) {
    parsed = { snippets: parsed, reason: null };
  }
} catch (error) {
  parsed = { snippets: [], reason: `ollama_parse_failed:${error.message}` };
}
const snippetArray = Array.isArray(parsed?.snippets) ? parsed.snippets : [];
const isQuoteLike = (text) => {
  const normalized = normalize(text);
  if (!normalized) return true;
  if (/["“”]/.test(text)) return true;
  return sourceTexts.some((source) => {
    const candidate = normalize(source);
    return candidate && (candidate === normalized || candidate.includes(normalized) || normalized.includes(candidate));
  });
};
const isOverSpecific = (text) => {
  return /@[A-Za-z0-9_]+/.test(text)
    || /\b\d{4}-\d{2}-\d{2}\b/.test(text)
    || /\b\d{1,2}:\d{2}\b/.test(text)
    || /ห้อง\s*\d+/i.test(text)
    || /รหัส\s*\d+/i.test(text)
    || /เลขที่\s*\d+/i.test(text)
    || /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/.test(text);
};
const impliesSingleStudent = (text) => /(คนหนึ่ง|หนึ่งคน|คนเดียว|รายเดียว)/i.test(text);
const genericPatterns = [
  /เรียนรู้อะไรหลาย/i,
  /เรียนรู้หลายอย่าง/i,
  /เรียนรู้หลายสิ่ง/i,
  /สนุกดี/i,
  /โอเคขึ้น/i,
  /ดีขึ้นเฉย/i,
  /เข้าใจมากขึ้น$/i,
  /วันนี้ดี/i,
  /โดยรวมดี/i,
  /^นักเรียนหลายคน$/i,
];
const classroomSignalPattern = /(อธิบาย|คำถาม|งาน|กิจกรรม|กลุ่ม|เพื่อน|เวลา|จังหวะ|เนื้อหา|ตัวอย่าง|ทบทวน|ร่วม|มั่นใจ|กดดัน|ไม่ทัน|เร็ว|ช้า|ตาม|สนับสนุน|ช่วย|อภิปราย|มีส่วนร่วม|ฟัง|เข้าใจ|สับสน|ภาระงาน|บรรยากาศ|ตอบคำถาม|ทำงานร่วม|ความชัดเจน|ยุติธรรม)/i;
const isLowInformation = (text, safetyNotes) => {
  const normalized = normalize(text);
  if (!normalized) return true;
  if (genericPatterns.some((pattern) => pattern.test(text))) return true;
  const compact = normalized.replace(/\s+/g, '');
  if (compact.length < 24) return true;
  if (!classroomSignalPattern.test(text) && !classroomSignalPattern.test(safetyNotes || '')) return true;
  return false;
};
const similarityScore = (left, right) => {
  if (!left || !right) return 0;
  if (left === right || left.includes(right) || right.includes(left)) return 1;
  const leftParts = left.split(/\s+/).filter(Boolean);
  const rightParts = right.split(/\s+/).filter(Boolean);
  if (leftParts.length === 0 || rightParts.length === 0) return 0;
  const leftSet = new Set(leftParts);
  const overlap = rightParts.filter((part) => leftSet.has(part)).length;
  return overlap / Math.max(leftParts.length, rightParts.length);
};
const validated = snippetArray
  .map((snippet) => {
    const text = typeof snippet?.text_redacted === 'string' ? snippet.text_redacted.replace(/\s+/g, ' ').trim() : '';
    const tone = typeof snippet?.tone === 'string' ? snippet.tone.trim().toLowerCase() : 'mixed';
    const safetyNotes = typeof snippet?.safety_notes === 'string' ? snippet.safety_notes.replace(/\s+/g, ' ').trim().slice(0, 160) : 'aggregated_paraphrase';
    if (!text || text.length < 16 || text.length > 280) return null;
    if (isQuoteLike(text) || isOverSpecific(text) || impliesSingleStudent(text) || isLowInformation(text, safetyNotes)) return null;
    return {
      text_redacted: text,
      tone: ['low', 'mixed', 'positive', 'negative'].includes(tone) ? (tone === 'negative' ? 'low' : tone) : 'mixed',
      week_start: input.week_start,
      source_window: input.source_window,
      contributing_students_count: Number(input.contributing_students_count || input.source_window?.n || 0),
      safety_notes: safetyNotes,
    };
  })
  .filter(Boolean);
const deduped = [];
for (const snippet of validated) {
  const key = normalize(snippet.text_redacted);
  if (!key) continue;
  const isNearDuplicate = deduped.some((existing) => similarityScore(normalize(existing.text_redacted), key) >= 0.7);
  if (isNearDuplicate) continue;
  deduped.push(snippet);
}
const finalSnippets = deduped.slice(0, 3);
const rejected = snippetArray.length > 0 && finalSnippets.length === 0;
return {
  json: {
    class_id: input.class_id,
    class_name: input.class_name,
    status: finalSnippets.length > 0 ? 'ready_to_write' : 'unsafe_output',
    batch_size: Number(input.batch_size || 0),
    snippets_written: finalSnippets.length,
    week_start: input.week_start,
    source_window: input.source_window,
    snippets: finalSnippets,
    reason: finalSnippets.length > 0 ? null : (parsed?.reason || 'ollama_output_rejected'),
    llm_output_rejected: rejected || finalSnippets.length === 0,
    llm_provider: input.llm_provider,
    llm_model: input.llm_model,
  }
};

const parsed = $('Parse Redaction Output').first().json;
const writeResult = $json || {};
const insertedCount = Number(writeResult.inserted_count || 0);
const status = parsed.status === 'ready_to_write' && insertedCount > 0
  ? 'written'
  : parsed.status;
return {
  json: {
    class_id: parsed.class_id,
    class_name: parsed.class_name,
    status,
    batch_size: Number(parsed.batch_size || 0),
    snippets_written: insertedCount,
    week_start: parsed.week_start,
    source_window: parsed.source_window,
    reason: status === 'written' ? null : (parsed.reason || status),
    llm_output_rejected: parsed.llm_output_rejected === true,
    llm_provider: parsed.llm_provider,
    llm_model: parsed.llm_model,
    inserted_count: insertedCount
  }
};
